cat > /etc/init.d/udevd << "EOF" #!/sbin/openrc-run # Starts the udevd daemon. # Authors: Zeckma - zeckma@linuxfromscratch.com # Version: LFS &version;
description="starts the udevd daemon"
command=/sbin/udevd command_background=yes pidfile="/run/${RC_SVCNAME}.pid"
depend() { after localnet after modules }
stop() { ebegin "Stopping ${RC_SVCNAME}" /bin/udevadm control --exit eend $? } EOF
cat > /etc/init.d/udev-trigger << "EOF" #!/sbin/openrc-run # Coldplugs devices and settles the udevd daemon. # Authors: Zeckma - zeckma@linuxfromscratch.com # Version: LFS &version;
description="coldplugs devices"
depend() { after udevd provides dev keyword -shutdown }
start() { ebegin "Coldplugging devices"
/bin/udevadm trigger --action=add --type=subsystems /bin/udevadm trigger --action=add --type=devices /bin/udevadm trigger --action=change --type=devices
# Wait for udevd to process the uevents we triggered /bin/udevadm settle --timeout=5
# If any LVM based partitions are on the system, ensure they # are activated so they can be used. if [ -x /sbin/vgchange ]; then /sbin/vgchange -a y >/dev/null; fi } EOF
for i in udev{d,-trigger}; do chmod 755 /etc/init.d/$i rc-update add $i sysinit done

cat > /etc/init.d/sysklogd << "EOF"
#!/sbin/openrc-run
# Starts the sysklogd daemon.
# Authors: Zeckma - zeckma@linuxfromscratch.com
# Version: LFS &version;

command=/sbin/syslogd
pidfile="/run/${RC_SVCNAME}.pid"
command_background=true
command_args="-F ${sysklogd_options}"

depend() {
  need clock hostname
  after root
  provide logger
}

reload() {
  ebegin "Reloading sysklogd"
  start-stop-daemon --signal HUP --pidfile ${pidfile}
  eend $?
}
EOF

chmod 755 /etc/init.d/sysklogd
rc-update add sysklogd boot
